extracted_python_code:
result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(status == "SUCCESS")) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    distinct_customers_count=COUNT(
        Customers.WHERE(
            ENDSWITH(email, ".com") & 
            HAS(
                transactions_made.WHERE(
                    (transaction_type == "BUY") &
                    (ISIN(ticker.symbol, ("AMZN", "AAPL", "GOOGL", "META", "NFLX")))
                )
            ) == 1
        )
    )
)

result = Customers.WHERE(
    (join_date >= "2023-01-01") & (status == "active")
).PARTITION(
    name="countries", by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

result = Customers.WHERE(country == "USA").CALCULATE(
    num_transactions = COUNT(
        transactions_made.WHERE(
            (date_time >= DATETIME('now', 'start of week', '-7 days')) &
            (date_time < DATETIME('now', 'start of week'))
        )
    ),
    total_amount = SUM(
        transactions_made.WHERE(
            (date_time >= DATETIME('now', 'start of week', '-7 days')) &
            (date_time < DATETIME('now', 'start of week'))
        ).amount
    )
)

result = Transactions.WHERE(
    (transaction_type == "buy") & 
    (DATEDIFF("days", date_time, DATETIME("now")) <= 10)
).CALCULATE(
    ticker_symbol = ticker.symbol
).PARTITION(
    name="ticker_groups", 
    by=ticker_symbol
).CALCULATE(
    ticker_symbol = ticker_symbol,
    num_buy_transactions = COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Customers.WHERE(
    HASNOT(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    customer_name=name
)

result = Customers.WHERE(
    HAS(transactions_made.WHERE(transaction_type == 'buy')) == 1
).CALCULATE(
    customer_id=_id
)

result = DailyPrices.WHERE(
    date >= "2023-04-01"
).PARTITION(name="tickers", by=ticker_id).CALCULATE(
    ticker_id
)

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == "VTI") & 
            (DATEDIFF("days", date, DATETIME("now")) <= 7)
        ).close
    )
)

result = Broker.CALCULATE(
    num_transactions = COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME('now')) <= 70
        ).transactions_made
    )
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF(
        "days", 
        join_date, 
        MIN(transactions_made.date_time)
    )
)

result = Customers.CALCULATE(
    customer_id=_id,
    customer_name=name,
    num_sell_transactions=COUNT(
        transactions_made.WHERE(
            (DATE(date_time) == "2023-04-01") & 
            (transaction_type == "sell")
        )
    )
).TOP_K(1, by=num_sell_transactions.DESC())

result = Dealership.CALCULATE(
    number_of_sales=COUNT(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (DATEDIFF("days", sale_date, DATETIME("now")) >= 0) &
            (car.make == "Toyota")
        )
    ),
    total_revenue=SUM(
        Sales.WHERE(
            (DATEDIFF("days", sale_date, DATETIME("now")) <= 30) &
            (DATEDIFF("days", sale_date, DATETIME("now")) >= 0) &
            (car.make == "Toyota")
        ).sale_price
    )
)

result = Dealership.CALCULATE(
    asp_q1_2023=AVG(
        Sales.WHERE(
            (YEAR(sale_date) == 2023) & 
            (MONTH(sale_date) >= 1) & 
            (MONTH(sale_date) <= 3)
        ).sale_price
    )
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

result = Dealership.CALCULATE(
    gpm = 100.0 * (
        SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price) - 
        SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
    ) / SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
)

# Find cars that were sold on the same day they went out of inventory
cars_sold_same_day = Cars.WHERE(
    HAS(
        sale_records.WHERE(
            HAS(
                Cars.inventory_snapshots.WHERE(
                    (is_in_inventory == False) & 
                    (snapshot_date == sale_date)
                )
            ) == 1
        )
    ) == 1
).CALCULATE(
    make=make,
    model=model,
    sale_price=sale_records.WHERE(
        HAS(
            Cars.inventory_snapshots.WHERE(
                (is_in_inventory == False) & 
                (snapshot_date == sale_date)
            )
        ) == 1
    ).SINGULAR().sale_price
)

# Get the car with the highest sale price
result = cars_sold_same_day.TOP_K(1, by=sale_price.DESC())

result = Dealership.CALCULATE(
    total_sales_count=COUNT(
        Sales.WHERE(
            DATEDIFF("days", sale_date, DATETIME("now")) <= 6
        )
    )
)

result = Customers.WHERE(
    HAS(car_purchases) == 1
).CALCULATE(
    customer_id=_id
)

result = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == "cash")) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') &
            (ISIN(DAYNAME(payment_date), ("Saturday", "Sunday")))
        )
    )
)

result = Drugs.WHERE(HAS(treatments_used_in) == 1).CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(~(end_dt == None)).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

result = DermTreatment.CALCULATE(
    num_gmail_yahoo_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == "Psoriasis vulgaris") & 
                    (drug.drug_type == "biologic")
                )
            ) == 1
        )
    )
)

result = DermTreatment.CALCULATE(
    alice_treatment_count=COUNT(
        Patients.WHERE(first_name == "Alice").treatments_received.WHERE(
            (start_dt >= DATETIME('now', 'start of month', '-6 months')) &
            (start_dt < DATETIME('now', 'start of month'))
        )
    )
)

result = Drugs.WHERE(drug_name == "Drugalin").CALCULATE(
    average_weight=AVG(treatments_used_in.patient.weight_kg)
)

result = DermTreatment.CALCULATE(
    caw_male=AVG(Patients.WHERE(gender == "Male").weight_kg)
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE(
        (gender == "Female") & (ins_type == "Private")
    ))
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=SUM(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) & 
            (MONTH(reported_dt) == MONTH(treatment.start_dt))
        ).CALCULATE(count=1).count
    )
).TOP_K(1, by=num_adverse_events.DESC())

result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(drug.drug_type == "biologic")) == 1
).PARTITION(name="states", by=loc_state).CALCULATE(
    loc_state
)

# Filter doctors who have treatments in the past 6 months
doctors_with_recent_treatments = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(
        DATEDIFF("months", start_dt, DATETIME("now")) <= 6
    )) == 1
)

# Group by specialty and calculate totals
specialty_stats = doctors_with_recent_treatments.PARTITION(
    name="specialties", 
    by=speciality
).CALCULATE(
    specialty=speciality,
    num_treatments=COUNT(
        Doctors.prescribed_treatments.WHERE(
            DATEDIFF("months", start_dt, DATETIME("now")) <= 6
        )
    ),
    total_drug_amount=SUM(
        Doctors.prescribed_treatments.WHERE(
            DATEDIFF("months", start_dt, DATETIME("now")) <= 6
        ).tot_drug_amt
    )
)

# Get top 3 specialties by total drug amount
result = specialty_stats.TOP_K(3, by=total_drug_amount.DESC())

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            CONTAINS(LOWER(diagnosis.diag_name), "psoriasis") &
            (HAS(drug.fda_appr_dt) == 1) &
            (DATEDIFF("days", end_dt, DATETIME("now")) <= 180) &
            (HAS(end_dt) == 1)
        )
    )
)

# Find doctors registered 2 years ago and get their first treatment
result = Doctors.WHERE(
    year_reg == YEAR(DATETIME('now', '-2 years'))
).CALCULATE(
    last_name=last_name,
    year_of_registration=year_reg,
    first_treatment_date=prescribed_treatments.WHERE(
        RANKING(by=start_dt.ASC(), per="Doctors") == 1
    ).SINGULAR().start_dt,
    first_treatment_id=prescribed_treatments.WHERE(
        RANKING(by=start_dt.ASC(), per="Doctors") == 1
    ).SINGULAR().treatment_id
)

result = DermTreatment.CALCULATE(
    average_age=AVG(
        Patients.WHERE(
            (gender == "M") & 
            (ins_type == "Private")
        ).CALCULATE(
            age=DATEDIFF("years", date_of_birth, DATETIME("now"))
        ).age
    )
)

result = Ewallet.CALCULATE(
    number_of_transactions = COUNT(
        Users.WHERE(country == "US").transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME("now")) <= 7
        )
    ),
    total_transaction_amount = SUM(
        Users.WHERE(country == "US").transactions_sent.WHERE(
            DATEDIFF("days", created_at, DATETIME("now")) <= 7
        ).amount
    )
)

result = Ewallet.CALCULATE(
    average_balance=AVG(
        UserBalances.WHERE(
            DATEDIFF("days", updated_at, DATETIME("now")) <= 7
        ).balance
    )
)

result = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Ewallet.CALCULATE(
    total_count = COUNT(
        UserSessions.WHERE(
            DATEDIFF("days", session_start_ts, DATETIME("now")) <= 30
        )
    )
)

result = Users.WHERE(
    (LOWER(country) == 'us') & 
    (HAS(notifications.WHERE(
        (notification_type == 'promotional') & 
        (status == 'unread')
    )) == 1)
).CALCULATE(
    username=username,
    unread_promotional_count=COUNT(notifications.WHERE(
        (notification_type == 'promotional') & 
        (status == 'unread')
    ))
)

result = Merchants.WHERE(
    HAS(transactions_received) == 1
).CALCULATE(
    merchant_id=mid
)

result = Notifications.WHERE(
    notification_type == "transaction"
).PARTITION(name="users", by=user_id).CALCULATE(
    user_id=user_id
)

result = Merchants.WHERE(
    (status == "active") & 
    (CONTAINS(category, "retail"))
).CALCULATE(
    median_balance = MEDIAN(balances.balance)
)

# First, find the earliest snapshot date in 2023
earliest_date_info = Ewallet.CALCULATE(
    earliest_snapshot_date=MIN(
        UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date
    )
)

# Then filter for snapshots from that date and calculate averages
result = earliest_date_info.UserSettingSnapshots.WHERE(
    snapshot_date == earliest_snapshot_date
).CALCULATE(
    avg_daily_limit=AVG(UserSettingSnapshots.tx_limit_daily),
    avg_monthly_limit=AVG(UserSettingSnapshots.tx_limit_monthly)
)

result = UserSessions.CALCULATE(
    device_type=device_type,
    duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
).PARTITION(
    name="device_groups", 
    by=device_type
).CALCULATE(
    device_type=device_type,
    avg_duration_seconds=AVG(UserSessions.duration_seconds)
)

users_without_early_notifications = Users.WHERE(
    HASNOT(
        notifications.WHERE(
            DATEDIFF("years", user.created_at, created_at) < 1
        )
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
